#####################################################################################
# Project: Coffee Rhizosphere Microbiome - 16S rRNA Metabarcoding
# Script: 04_alpha_diversity.R
# Author: Gustavo Goncalves
# Last edit: 18/11/2026
#
# Description:
# Exploratory analysis of alpha diversity in coffee rhizosphere microbiome samples.
# Calculates Observed richness and Shannon diversity, generates exploratory plots,
# and saves figures and alpha diversity metrics.
#
# Notes:
#   This script requires the phyloseq object generated by 03_phyloseq_object.R.
#####################################################################################

# Load project configuration
source("projects/coffee/config.R")

# Set up packages
library(phyloseq); packageVersion("phyloseq")
library(ggplot2); packageVersion("ggplot2")

theme_set(theme_bw())

# Create alpha diversity directory
alpha_path <- file.path(results_path, "alpha_diversity")
dir.create(alpha_path, recursive = TRUE, showWarnings = FALSE)

# Load phyloseq object
ps <- readRDS(file.path(objects_path, "phyloseq_object.rds"))


#####################################################################################
# Calculate alpha diversity
#####################################################################################

alpha <- estimate_richness(
  ps,
  measures = c("Observed", "Shannon")
)

# Add sample metadata
metadata <- data.frame(sample_data(ps))

alpha <- cbind(
  alpha,
  metadata[rownames(alpha), , drop = FALSE]
)

# Save alpha diversity table
write.csv(
  alpha,
  file.path(alpha_path, "alpha_diversity_metrics.csv"),
  row.names = TRUE
)


#####################################################################################
# Exploratory plots
#####################################################################################

# Observed richness and Shannon diversity - Farm x CropStage
p1 <- plot_richness(
  ps,
  x = "Farm",
  measures = c("Observed", "Shannon"),
  color = "CropStage"
)

print(p1)

ggsave(
  filename = file.path(alpha_path, "alpha_diversity_farm_cropstage.png"),
  plot = p1,
  width = 12,
  height = 6,
  dpi = 300
)


# Observed richness and Shannon diversity - Farm x CropStage, faceted by Year
p2 <- plot_richness(
  ps,
  x = "Farm",
  measures = c("Observed", "Shannon"),
  color = "CropStage"
) +
  facet_wrap(~Year)

print(p2)

ggsave(
  filename = file.path(alpha_path, "alpha_diversity_farm_cropstage_year.png"),
  plot = p2,
  width = 12,
  height = 8,
  dpi = 300
)


#####################################################################################
# Alpha diversity x pH
#####################################################################################

# Shannon diversity x pH
p3 <- ggplot(
  alpha,
  aes(
    x = pH,
    y = Shannon
  )
) +
  geom_point() +
  geom_smooth(
    method = "lm",
    se = TRUE
  ) +
  labs(
    x = "Soil pH",
    y = "Shannon diversity"
  )

print(p3)

ggsave(
  filename = file.path(alpha_path, "shannon_vs_ph.png"),
  plot = p3,
  width = 8,
  height = 6,
  dpi = 300
)


# Observed richness x pH
p4 <- ggplot(
  alpha,
  aes(
    x = pH,
    y = Observed
  )
) +
  geom_point() +
  geom_smooth(
    method = "lm",
    se = TRUE
  ) +
  labs(
    x = "Soil pH",
    y = "Observed ASV richness"
  )

print(p4)

ggsave(
  filename = file.path(alpha_path, "observed_vs_ph.png"),
  plot = p4,
  width = 8,
  height = 6,
  dpi = 300
)
